/**
 * projectsController.js
 * ──────────────────────
 * Controller: Miradi ya Usharika (Church Projects Module)
 * Ref: BSS-KKKT-2026-008
 *
 * Covers §9 (Ardhi na Majengo), §10 (Mikataba), §13 (Miradi)
 * of the KKKT Yombo database spec.
 *
 * Route mount point (app.js):
 *   app.use('/api/projects', projectRoutes);
 *
 * Auth model (mirrors authController.js pattern):
 *   authenticate  — JWT required on all routes
 *   authorize()   — role guard: 'pastor','elder','group_leader','member'
 *
 * R2 upload URLs are generated by the existing /api/r2 routes and
 * passed in as file_url strings — this controller only stores them.
 */

'use strict';

const db = require('../config/db');

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Build a WHERE clause + params array from a plain conditions object.
 * e.g. where({ 'p.status': 'active', 'p.project_type': null })
 *   → { clause: 'WHERE p.status = ?', params: ['active'] }
 * Null/undefined values are skipped.
 */
function buildWhere(conditions) {
  const parts  = [];
  const params = [];
  for (const [col, val] of Object.entries(conditions)) {
    if (val === undefined || val === null || val === '') continue;
    parts.push(`${col} = ?`);
    params.push(val);
  }
  return {
    clause: parts.length ? `WHERE ${parts.join(' AND ')}` : '',
    params,
  };
}

/** Safe integer parser — returns null on falsy/NaN. */
function intOrNull(v) {
  const n = parseInt(v, 10);
  return isNaN(n) ? null : n;
}

/**
 * Clamp a page/limit pair and return { page, limit, offset }.
 *
 * Uses bitwise OR (| 0) to guarantee strict 32-bit integers for limit and
 * offset. mysql2's prepared-statement executor requires this — passing
 * Number() / float64 values for LIMIT/OFFSET bindings throws:
 *   "Incorrect arguments to mysqld_stmt_execute"
 */
function paginate(query) {
  const page   = Math.max(1, parseInt(query.page,  10) || 1);
  const limit  = Math.min(200, Math.max(1, parseInt(query.limit, 10) || 50));
  const offset = (page - 1) * limit;
  return {
    page,
    limit:  limit  | 0,
    offset: offset | 0,
  };
}


// ─────────────────────────────────────────────────────────────────────────────
// Add this helper near the top of the file, alongside buildWhere / paginate
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Sanitize a params array before passing to db.execute().
 * mysql2 prepared statements reject NaN, Infinity, plain objects, and arrays.
 * - NaN / Infinity → null
 * - object / array → JSON string (last-resort; ideally fix at call site)
 * - everything else passes through unchanged
 */
function sanitizeParams(params) {
  return params.map((v) => {
    if (v === null || v === undefined) return null;
    if (typeof v === 'number' && !isFinite(v)) return null;   // NaN, Infinity
    if (typeof v === 'object') return JSON.stringify(v);       // shouldn't happen
    return v;
  });
}


