// ── GET /api/projects ─────────────────────────────────────────────────────────
// List projects with optional filters, pagination, and summary totals.
//
// Query params:
//   status        — planning|active|on_hold|completed|cancelled
//   project_type  — free-text filter (prefix match)
//   supervised_by — user id
//   search        — matches name, description
//   page, limit
exports.listProjects = async (req, res, next) => {
  try {
    const { page, limit, offset } = paginate(req.query);

    const conditions  = [];
    const whereParams = [];

    if (req.query.status) {
      conditions.push('p.status = ?');
      whereParams.push(String(req.query.status));
    }
    if (req.query.project_type) {
      conditions.push('p.project_type LIKE ?');
      whereParams.push(`${String(req.query.project_type)}%`);
    }
    if (req.query.supervised_by) {
      const sid = intOrNull(req.query.supervised_by);
      if (sid !== null) {
        conditions.push('p.supervised_by_id = ?');
        whereParams.push(sid);
      }
    }
    if (req.query.search) {
      conditions.push('(p.name LIKE ? OR p.description LIKE ?)');
      const like = `%${String(req.query.search)}%`;
      whereParams.push(like, like);
    }

    const whereClause = conditions.length
      ? `WHERE ${conditions.join(' AND ')}`
      : '';

      // ── COUNT ──────────────────────────────────────────────────────────────
    const safeLimit  = limit  | 0;
    const safeOffset = offset | 0;

    let total, projects;

    if (whereParams.length === 0) {
      // No filter params — mysql2 chokes on LIMIT/OFFSET bindings when the
      // params array contains only integers (same bug fixed in listLandAssets).
      // Use db.query() (non-prepared path) with values inlined into the SQL.
      const [[countRow]] = await db.query(
        `SELECT COUNT(*) AS total FROM projects p`
      );
      total = countRow.total;

      const listSql = `SELECT
         p.id, p.name, p.description, p.project_type, p.status,
         p.progress_pct, p.start_date, p.expected_end_date, p.actual_end_date,
         p.budget, p.total_paid, p.notes, p.land_asset_id,
         p.created_at, p.updated_at,
         u_sup.full_name   AS supervised_by_name,
         u_sup.id          AS supervised_by_id,
         u_cre.full_name   AS created_by_name,
         la.name           AS land_asset_name,
         (SELECT COUNT(*) FROM project_contracts pc  WHERE pc.project_id  = p.id) AS contract_count,
         (SELECT COUNT(*) FROM project_payments  pp  WHERE pp.project_id  = p.id) AS payment_count,
         (SELECT COUNT(*) FROM project_photos    pph WHERE pph.project_id = p.id) AS photo_count
       FROM projects p
       LEFT JOIN users       u_sup ON u_sup.id = p.supervised_by_id
       LEFT JOIN users       u_cre ON u_cre.id = p.created_by_id
       LEFT JOIN land_assets la    ON la.id    = p.land_asset_id
       ORDER BY p.created_at DESC
       LIMIT ${safeLimit} OFFSET ${safeOffset}`;

      [projects] = await db.query(listSql);

    } else {
      // Filter params present — string values in the array let prepared
      // statements handle LIMIT/OFFSET safely via | 0.
      const [[countRow]] = await db.execute(
        `SELECT COUNT(*) AS total FROM projects p ${whereClause}`,
        [...whereParams]
      );
      total = countRow.total;

      [projects] = await db.execute(
        `SELECT
           p.id, p.name, p.description, p.project_type, p.status,
           p.progress_pct, p.start_date, p.expected_end_date, p.actual_end_date,
           p.budget, p.total_paid, p.notes, p.land_asset_id,
           p.created_at, p.updated_at,
           u_sup.full_name   AS supervised_by_name,
           u_sup.id          AS supervised_by_id,
           u_cre.full_name   AS created_by_name,
           la.name           AS land_asset_name,
           (SELECT COUNT(*) FROM project_contracts pc  WHERE pc.project_id  = p.id) AS contract_count,
           (SELECT COUNT(*) FROM project_payments  pp  WHERE pp.project_id  = p.id) AS payment_count,
           (SELECT COUNT(*) FROM project_photos    pph WHERE pph.project_id = p.id) AS photo_count
         FROM projects p
         LEFT JOIN users       u_sup ON u_sup.id = p.supervised_by_id
         LEFT JOIN users       u_cre ON u_cre.id = p.created_by_id
         LEFT JOIN land_assets la    ON la.id    = p.land_asset_id
         ${whereClause}
         ORDER BY p.created_at DESC
         LIMIT ? OFFSET ?`,
        [...whereParams, safeLimit, safeOffset]
      );
    }
    
    return res.json({
      success: true,
      meta: { total, page, limit, pages: Math.ceil(total / limit) },
      projects,
    });
  } catch (err) { next(err); }
};


// ── GET /api/projects/:id ─────────────────────────────────────────────────────
// Full project detail — includes contracts, payments summary, latest 6 photos.
exports.getProject = async (req, res, next) => {
  try {
    const { id } = req.params;

    const [rows] = await db.execute(
      `SELECT
         p.*,
         u_sup.full_name  AS supervised_by_name,
         u_cre.full_name  AS created_by_name,
         la.name          AS land_asset_name,
         la.area_name     AS land_asset_area,
         la.plot_number   AS land_asset_plot
       FROM projects p
       LEFT JOIN users       u_sup ON u_sup.id = p.supervised_by_id
       LEFT JOIN users       u_cre ON u_cre.id = p.created_by_id
       LEFT JOIN land_assets la    ON la.id    = p.land_asset_id
       WHERE p.id = ?`,
      [id]
    );

    if (rows.length === 0) {
      return res.status(404).json({ success: false, message: 'Project not found.' });
    }

    // Contracts
    const [contracts] = await db.execute(
      `SELECT
         pc.*,
         u.full_name AS supervised_by_name,
         (SELECT SUM(pp.amount)
            FROM project_payments pp WHERE pp.contract_id = pc.id) AS total_paid,
         (SELECT COUNT(*) FROM contract_variations cv WHERE cv.contract_id = pc.id)
           AS variation_count
       FROM project_contracts pc
       LEFT JOIN users u ON u.id = pc.supervised_by_id
       WHERE pc.project_id = ?
       ORDER BY pc.created_at ASC`,
      [id]
    );

    // Latest 6 progress photos
    const [photos] = await db.execute(
      `SELECT id, file_url, thumbnail_url, caption, taken_date, progress_pct_at_photo, sort_order
       FROM project_photos
       WHERE project_id = ?
       ORDER BY sort_order ASC, taken_date DESC
       LIMIT 6`,
      [id]
    );

    // Payment summary by type
    const [paymentSummary] = await db.execute(
      `SELECT payment_type, COUNT(*) AS count, SUM(amount) AS total
       FROM project_payments
       WHERE project_id = ?
       GROUP BY payment_type`,
      [id]
    );

    return res.json({
      success: true,
      project: { ...rows[0], contracts, photos, payment_summary: paymentSummary },
    });
  } catch (err) { next(err); }
};


// ── POST /api/projects ────────────────────────────────────────────────────────
exports.createProject = async (req, res, next) => {
  try {
    const {
      name,
      description,
      project_type,
      status          = 'planning',
      progress_pct    = 0,
      start_date,
      expected_end_date,
      actual_end_date,
      budget,
      supervised_by_id,
      land_asset_id,
      notes,
    } = req.body;

    if (!name || !String(name).trim()) {
      return res.status(400).json({ success: false, message: 'Project name (jina la mradi) is required.' });
    }

    const [result] = await db.execute(
      `INSERT INTO projects (
         name, description, project_type,
         status, progress_pct,
         start_date, expected_end_date, actual_end_date,
         budget,
         supervised_by_id, land_asset_id,
         notes, created_by_id
       ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        String(name).trim(),
        description       || null,
        project_type      || null,
        status,
        Math.min(100, Math.max(0, parseInt(progress_pct, 10) || 0)),
        start_date        || null,
        expected_end_date || null,
        actual_end_date   || null,
        budget            ? parseFloat(budget) : null,
        intOrNull(supervised_by_id),
        intOrNull(land_asset_id),
        notes             || null,
        req.user.id,
      ]
    );

    return res.status(201).json({
      success:    true,
      message:    'Mradi umeundwa.',
      project_id: result.insertId,
    });
  } catch (err) { next(err); }
};


// ── PATCH /api/projects/:id ───────────────────────────────────────────────────
exports.updateProject = async (req, res, next) => {
  try {
    const { id } = req.params;

    const [existing] = await db.execute('SELECT id FROM projects WHERE id = ?', [id]);
    if (existing.length === 0) {
      return res.status(404).json({ success: false, message: 'Project not found.' });
    }

    const fields = [
      'name', 'description', 'project_type',
      'status', 'progress_pct',
      'start_date', 'expected_end_date', 'actual_end_date',
      'budget',
      'supervised_by_id', 'land_asset_id',
      'notes',
    ];

    const setClauses = [];
    const setParams  = [];

    for (const f of fields) {
      if (req.body[f] !== undefined) {
        setClauses.push(`${f} = ?`);
        setParams.push(
          f === 'progress_pct'
            ? Math.min(100, Math.max(0, parseInt(req.body[f], 10) || 0))
            : req.body[f] === '' ? null : req.body[f]
        );
      }
    }

    if (setClauses.length === 0) {
      return res.status(400).json({ success: false, message: 'No fields to update.' });
    }

    await db.execute(
      `UPDATE projects SET ${setClauses.join(', ')} WHERE id = ?`,
      [...setParams, id]
    );

    return res.json({ success: true, message: 'Mradi umesasishwa.' });
  } catch (err) { next(err); }
};


// ── DELETE /api/projects/:id ──────────────────────────────────────────────────
// Soft-delete not in spec; CASCADE deletes child rows via FK.
// Restricted to pastor/elder (enforced in router).
exports.deleteProject = async (req, res, next) => {
  try {
    const { id } = req.params;
    const [existing] = await db.execute('SELECT id, name FROM projects WHERE id = ?', [id]);
    if (existing.length === 0) {
      return res.status(404).json({ success: false, message: 'Project not found.' });
    }

    await db.execute('DELETE FROM projects WHERE id = ?', [id]);

    console.log(`Admin ${req.user.name} deleted project id=${id} "${existing[0].name}"`);
    return res.json({ success: true, message: 'Mradi umefutwa.' });
  } catch (err) { next(err); }
};


