// ── GET /api/projects/:projectId/contracts/:contractId/variations ─────────────
exports.listVariations = async (req, res, next) => {
  try {
    const { contractId } = req.params;
    const [variations] = await db.execute(
      `SELECT cv.*, u.full_name AS approved_by_name
       FROM contract_variations cv
       LEFT JOIN users u ON u.id = cv.approved_by_id
       WHERE cv.contract_id = ?
       ORDER BY cv.variation_number ASC`,
      [contractId]
    );
    return res.json({ success: true, variations });
  } catch (err) { next(err); }
};


// ── POST /api/projects/:projectId/contracts/:contractId/variations ────────────
exports.createVariation = async (req, res, next) => {
  try {
    const { projectId, contractId } = req.params;

    const [contract] = await db.execute(
      'SELECT id FROM project_contracts WHERE id = ? AND project_id = ?',
      [contractId, projectId]
    );
    if (contract.length === 0) {
      return res.status(404).json({ success: false, message: 'Contract not found.' });
    }

    // Auto-assign next variation number for this contract
    const [[{ next_no }]] = await db.execute(
      'SELECT COALESCE(MAX(variation_number), 0) + 1 AS next_no FROM contract_variations WHERE contract_id = ?',
      [contractId]
    );

    const {
      title,
      description,
      amount        = 0,
      status        = 'pending',
      approved_by_id,
      approved_date,
      notes,
    } = req.body;

    if (!title || !String(title).trim()) {
      return res.status(400).json({ success: false, message: 'Variation title is required.' });
    }

    const [result] = await db.execute(
      `INSERT INTO contract_variations (
         contract_id, project_id, variation_number,
         title, description, amount,
         status, approved_by_id, approved_date, notes
       ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        contractId,
        projectId,
        next_no,
        String(title).trim(),
        description    || null,
        parseFloat(amount) || 0,
        status,
        intOrNull(approved_by_id),
        approved_date  || null,
        notes          || null,
      ]
    );

    // If approved, update contract revised_value immediately
    if (status === 'approved') {
      await db.execute(
        `UPDATE project_contracts
         SET revised_value = COALESCE(revised_value, contract_value) + ?
         WHERE id = ?`,
        [parseFloat(amount) || 0, contractId]
      );
    }

    return res.status(201).json({
      success:      true,
      message:      'Variation imeundwa.',
      variation_id: result.insertId,
      variation_no: next_no,
    });
  } catch (err) { next(err); }
};


// ── PATCH /api/projects/:projectId/contracts/:contractId/variations/:variationId
exports.updateVariation = async (req, res, next) => {
  try {
    const { contractId, variationId } = req.params;

    const [existing] = await db.execute(
      'SELECT id, status, amount FROM contract_variations WHERE id = ? AND contract_id = ?',
      [variationId, contractId]
    );
    if (existing.length === 0) {
      return res.status(404).json({ success: false, message: 'Variation not found.' });
    }

    const { title, description, amount, status, approved_by_id, approved_date, notes } = req.body;

    const setClauses = [];
    const setParams  = [];
    const updatable  = { title, description, amount, status, approved_by_id, approved_date, notes };

    for (const [k, v] of Object.entries(updatable)) {
      if (v !== undefined) {
        setClauses.push(`${k} = ?`);
        setParams.push(v === '' ? null : v);
      }
    }
    if (setClauses.length === 0) {
      return res.status(400).json({ success: false, message: 'No fields to update.' });
    }

    await db.execute(
      `UPDATE contract_variations SET ${setClauses.join(', ')} WHERE id = ?`,
      [...setParams, variationId]
    );

    // Recalculate revised_value from approved variations whenever status or amount changes
    if (status !== undefined || amount !== undefined) {
      await db.execute(
        `UPDATE project_contracts pc
         SET revised_value = pc.contract_value + (
           SELECT COALESCE(SUM(cv.amount), 0)
           FROM contract_variations cv
           WHERE cv.contract_id = ? AND cv.status = 'approved'
         )
         WHERE pc.id = ?`,
        [contractId, contractId]
      );
    }

    return res.json({ success: true, message: 'Variation imesasishwa.' });
  } catch (err) { next(err); }
};


