// ── GET /api/projects/:projectId/documents ────────────────────────────────────
exports.listDocuments = async (req, res, next) => {
  try {
    const { projectId } = req.params;
    const confidentialFilter = req.query.confidential; // '0' or '1'

    const conditions  = ['pd.project_id = ?'];
    const queryParams = [projectId];

    // Non-pastor/elder users cannot see confidential docs
    const isAdmin = ['pastor', 'elder'].includes(req.user.role);
    if (!isAdmin) {
      conditions.push('pd.confidential = 0');
    } else if (confidentialFilter !== undefined) {
      conditions.push('pd.confidential = ?');
      queryParams.push(parseInt(confidentialFilter, 10));
    }

    if (req.query.document_type) {
      conditions.push('pd.document_type = ?');
      queryParams.push(req.query.document_type);
    }
    if (req.query.contract_id) {
      conditions.push('pd.contract_id = ?');
      queryParams.push(intOrNull(req.query.contract_id));
    }

    const [documents] = await db.execute(
      `SELECT pd.*, u.full_name AS uploaded_by_name
       FROM project_documents pd
       LEFT JOIN users u ON u.id = pd.uploaded_by_id
       WHERE ${conditions.join(' AND ')}
       ORDER BY pd.uploaded_at DESC`,
      queryParams
    );

    return res.json({ success: true, documents });
  } catch (err) { next(err); }
};


