// §9 — LAND ASSETS (ardhi na majengo)
// ═══════════════════════════════════════════════════════════════════════════════

// ── GET /api/projects/land-assets ─────────────────────────────────────────────
exports.listLandAssets = async (req, res, next) => {
  try {
    const { page, limit, offset } = paginate(req.query);

    const conditions  = ['la.is_active = 1'];
    const queryParams = [];

    if (req.query.asset_type) {
      conditions.push('la.asset_type = ?');
      queryParams.push(String(req.query.asset_type));
    }
    if (req.query.ownership_status) {
      conditions.push('la.ownership_status = ?');
      queryParams.push(String(req.query.ownership_status));
    }
    if (req.query.search) {
      conditions.push('(la.name LIKE ? OR la.area_name LIKE ? OR la.plot_number LIKE ?)');
      const like = `%${String(req.query.search)}%`;
      queryParams.push(like, like, like);
    }

    const whereClause = `WHERE ${conditions.join(' AND ')}`;

    // Safe integers for LIMIT/OFFSET — Math.trunc strips any fractional part.
    const safeLimit  = Math.trunc(limit);
    const safeOffset = Math.trunc(offset);

    const countSql = `SELECT COUNT(*) AS total FROM land_assets la ${whereClause}`;

    const selectSql = `
      SELECT
        la.*,
        u.full_name AS responsible_name,
        (SELECT COUNT(*) FROM projects p
           WHERE p.land_asset_id = la.id) AS linked_project_count,
        (SELECT COUNT(*) FROM land_asset_documents lad
           WHERE lad.land_asset_id = la.id) AS document_count
      FROM land_assets la
      LEFT JOIN users u ON u.id = la.responsible_id
      ${whereClause}
      ORDER BY la.name ASC`;

    let total, assets;

    if (queryParams.length === 0) {
      // No user-supplied filter params.
      // db.execute([]) crashes (empty-array bug in mysql2).
      // db.execute([limit, offset]) crashes too (SMI/double mismatch).
      // Fix: db.query() — non-prepared path — with the integers inlined
      // directly into the SQL string. No binding, no type inspection.
      const [[countRow]] = await db.query(countSql);
      total = countRow.total;

      const [rows] = await db.query(`${selectSql} LIMIT ${safeLimit} OFFSET ${safeOffset}`);
      assets = rows;
    } else {
      // Filter params present — prepared statements work fine because the
      // array is non-empty and string params precede limit/offset.
      const [[countRow]] = await db.execute(countSql, queryParams);
      total = countRow.total;

      const [rows] = await db.execute(
        `${selectSql} LIMIT ? OFFSET ?`,
        [...queryParams, safeLimit, safeOffset]
      );
      assets = rows;
    }

    return res.json({
      success: true,
      meta:    { total, page, limit, pages: Math.ceil(total / limit) },
      assets,
    });
  } catch (err) { next(err); }
};

// ── GET /api/projects/land-assets/:id ────────────────────────────────────────
exports.getLandAsset = async (req, res, next) => {
  try {
    const { id } = req.params;

    const [rows] = await db.execute(
      `SELECT la.*, u.full_name AS responsible_name
       FROM land_assets la
       LEFT JOIN users u ON u.id = la.responsible_id
       WHERE la.id = ?`,
      [id]
    );
    if (rows.length === 0) {
      return res.status(404).json({ success: false, message: 'Land asset not found.' });
    }

    // Documents — filter confidential for non-admin roles
    const isAdmin   = ['pastor', 'elder'].includes(req.user.role);
    const docFilter = isAdmin ? '' : 'AND lad.confidential = 0';

    const [documents] = await db.execute(
      `SELECT lad.*, u.full_name AS uploaded_by_name
       FROM land_asset_documents lad
       LEFT JOIN users u ON u.id = lad.uploaded_by_id
       WHERE lad.land_asset_id = ? ${docFilter}
       ORDER BY lad.uploaded_at DESC`,
      [id]
    );

    // Linked projects
    const [projects] = await db.execute(
      `SELECT id, name, status, progress_pct, start_date
       FROM projects
       WHERE land_asset_id = ?
       ORDER BY start_date DESC`,
      [id]
    );

    return res.json({
      success: true,
      asset:   { ...rows[0], documents, linked_projects: projects },
    });
  } catch (err) { next(err); }
};


